cd /home/user/Rare-cancers/research/manuscripts && python3 -c "
import json
d=json.load(open('emc-mortality-decomposition.json'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items(): walk(v,p+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,p+'[%d]'%i)
    else:
        print(p,'=',repr(o))
walk(d)
" | head -200

